    },
    {
      "muscleGroup": "Shoulders",
      "severity": "mild",
      "observation": "Shoulders account for only 10.4% of total volume with 4 sets, which is lower than the primary pushing and pulling muscles. For balanced upper body development, slightly more direct shoulder work could be beneficial, especially as chest and back volume are each nearly three times higher."
    }
  ],
  "deloadRecommended": false,
